from functools import lru_cache
@lru_cache(None)
def shapes(n):
 if n==1:return ('L',)
 return tuple((a,b) for i in range(1,n) for a in shapes(i) for b in shapes(n-i))
@lru_cache(None)
def rgs(n):
 if n==0:return ((),)
 out=[]
 for p in rgs(n-1):
  for x in range(max(p,default=-1)+2): out.append(p+(x,))
 return tuple(out)
[len(shapes(n)) for n in range(1,9)],[len(rgs(n)) for n in range(1,9)]

def shape_schedule(s):
 leaves=[]; gates=[]
 def rec(x):
  if x=='L':
   q=len(leaves); leaves.append(q); return q
  a=rec(x[0]); b=rec(x[1]); q=len(leaves) # wrong because total leaf unknown
  # use tagged gate
  q=('g',len(gates));gates.append((q,a,b));return q
 root=rec(s);return gates,root
# optimized auditor

def audit_one(s, part):
 n=len(part); w=max(4,1<<(n-1).bit_length()); l=w.bit_length()-1
 gates,root=shape_schedule(s)
 # tokens leaf ints, gate tuples
 k=max(part)+1
 lanes=[None]*w; loc={}
 occ=[[] for _ in range(k)]
 for i,v in enumerate(part):occ[v].append(i)
 # truth bitsets assignments lex with variable bits index assignment integer bit v
 mask=(1<<(1<<k))-1
 val={}
 for v in range(k):
  tv=sum(1<<a for a in range(1<<k) if (a>>v)&1)
  base=occ[v][0]; lanes[v]=base;loc[base]=v;val[base]=tv
 stage=0
 def emit(dim):
  nonlocal stage
  def cur():return (stage//2)%l
  while cur()!=dim:stage+=1
  stage+=1
 def swap(a,b):
  d=(a^b).bit_length()-1;emit(d)
  ta,tb=lanes[a],lanes[b];lanes[a],lanes[b]=tb,ta
  if ta is not None:loc[ta]=b
  if tb is not None:loc[tb]=a
 for v in range(k):
  base=occ[v][0]
  for new in occ[v][1:]:
   a=loc[base];free=lanes.index(None);ds=[d for d in range(l) if (a^free)>>d&1]
   for d in ds[:-1]:
    b=a^(1<<d);swap(a,b);a=b
   d=ds[-1];emit(d);lanes[free]=new;loc[new]=free;val[new]=val[base]
 for out,left,right in gates:
  a,b=loc[left],loc[right];ds=[d for d in range(l) if (a^b)>>d&1]
  for d in ds[:-1]:
   c=a^(1<<d);swap(a,c);a=c
  emit(ds[-1]);
  del loc[left];del loc[right];lanes[a]=out;lanes[b]=None;loc[out]=a
  val[out]=mask ^ (val[left]&val[right])
 budget=m.stage_budget(w)
 if not stage<budget:return ('budget',n,w,stage,budget,s,part)
 # independently recursive bit eval
 it=iter(range(n))
 def ev(x):
  if x=='L':return val[next(it)]
  return mask^(ev(x[0])&ev(x[1]))
 expected=ev(s)
 if val[root]!=expected:return ('value',s,part,val[root],expected)
 return stage

for n in range(1,7):
 t=time.time();mx=0;cnt=0
 for s in shapes(n):
  for part in rgs(n):
   z=audit_one(s,part);cnt+=1
   if isinstance(z,tuple):print('FAIL',z);raise SystemExit
   mx=max(mx,z)
 print(n,cnt,mx,time.time()-t)

for n in [7,8]:
